function enc($v) { if (is_int($v)) return "i:$v"; if (is_float($v)) return "f:".bin2hex(pack('E', $v)); if (is_bool($v)) return "b:".(int)$v; if (is_null($v)) return "n:"; return "s:".bin2hex($v); }
foreach ($q as $c) {
  $fmt = array_shift($c);
  $line = bin2hex($fmt) . "\t" . implode(',', array_map('enc', $c)) . "\t";
  set_error_handler(function($no, $str) use (&$ws) { $ws[] = $str; return true; });
  $ws = [];
  try { $r = sprintf($fmt, ...$c); $line .= "R:" . bin2hex($r); foreach ($ws as $w) $line .= "\tW:".$w; }
